import type { DateTimeDuration } from "@internationalized/date";

import type { AdapterOptions } from "./context";
import { fromZonedLike, toZoned } from "./convert";

function applyDuration<T extends Date>(
  date: T,
  duration: DateTimeDuration,
  options?: AdapterOptions,
): T {
  const zoned = toZoned(date, options?.timeZone);
  return fromZonedLike(date, zoned.add(duration));
}

function applyNegativeDuration<T extends Date>(
  date: T,
  duration: DateTimeDuration,
  options?: AdapterOptions,
): T {
  const zoned = toZoned(date, options?.timeZone);
  return fromZonedLike(date, zoned.subtract(duration));
}

/**
 * Each pair below has the same name and signature as its date-fns
 * counterpart (`addDays(date, amount)`), so a call site that does
 *
 *   import { addDays } from 'date-fns'
 *
 * keeps working unmodified after switching the import to this package —
 * only now DST transitions, month-length overflow ("Jan 31 + 1 month"),
 * and non-Gregorian calendars are handled by `@internationalized/date`'s
 * calendar engine instead of by hand-rolled millisecond math.
 *
 * Every function here is generic over `T extends Date` (matching real
 * date-fns v4's own typing convention) so a `TZDate` input infers a
 * `TZDate` return with no cast at the call site — `addDays(someTZDate, 1)`
 * is typed `TZDate`, not widened to `Date`.
 */

export function addYears<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyDuration(date, { years: amount }, options);
}
export function subYears<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyNegativeDuration(date, { years: amount }, options);
}

export function addMonths<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyDuration(date, { months: amount }, options);
}
export function subMonths<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyNegativeDuration(date, { months: amount }, options);
}

export function addWeeks<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyDuration(date, { weeks: amount }, options);
}
export function subWeeks<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyNegativeDuration(date, { weeks: amount }, options);
}

export function addDays<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyDuration(date, { days: amount }, options);
}
export function subDays<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyNegativeDuration(date, { days: amount }, options);
}

export function addHours<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyDuration(date, { hours: amount }, options);
}
export function subHours<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyNegativeDuration(date, { hours: amount }, options);
}

export function addMinutes<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyDuration(date, { minutes: amount }, options);
}
export function subMinutes<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyNegativeDuration(date, { minutes: amount }, options);
}

export function addSeconds<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyDuration(date, { seconds: amount }, options);
}
export function subSeconds<T extends Date>(date: T, amount: number, options?: AdapterOptions): T {
  return applyNegativeDuration(date, { seconds: amount }, options);
}

export function addMilliseconds<T extends Date>(
  date: T,
  amount: number,
  options?: AdapterOptions,
): T {
  return applyDuration(date, { milliseconds: amount }, options);
}
export function subMilliseconds<T extends Date>(
  date: T,
  amount: number,
  options?: AdapterOptions,
): T {
  return applyNegativeDuration(date, { milliseconds: amount }, options);
}

/** Generic escape hatch mirroring date-fns's `add`/`sub`, taking a full duration object. */
export function add<T extends Date>(
  date: T,
  duration: DateTimeDuration,
  options?: AdapterOptions,
): T {
  return applyDuration(date, duration, options);
}
export function sub<T extends Date>(
  date: T,
  duration: DateTimeDuration,
  options?: AdapterOptions,
): T {
  return applyNegativeDuration(date, duration, options);
}

import {
  type DayOfWeek,
  endOfMonth as intlEndOfMonth,
  endOfWeek as intlEndOfWeek,
  endOfYear as intlEndOfYear,
  startOfMonth as intlStartOfMonth,
  startOfWeek as intlStartOfWeek,
  startOfYear as intlStartOfYear,
} from "@internationalized/date";

import type { AdapterOptions } from "./context";
import { getDefaultLocale } from "./context";
import { fromZonedLike, toZoned } from "./convert";

const END_OF_DAY_FIELDS = {
  hour: 23,
  minute: 59,
  second: 59,
  millisecond: 999,
} as const;
const START_OF_DAY_FIELDS = {
  hour: 0,
  minute: 0,
  second: 0,
  millisecond: 0,
} as const;

/** date-fns's numeric `weekStartsOn` (0 = Sunday .. 6 = Saturday) mapped to `@internationalized/date`'s `DayOfWeek`. */
const WEEKDAY_BY_INDEX: DayOfWeek[] = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];

export interface WeekOptions extends AdapterOptions {
  /** 0 (Sunday) through 6 (Saturday), matching date-fns's `weekStartsOn`. Defaults to the locale's convention. */
  weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6;
}

export function startOfDay<T extends Date>(date: T, options?: AdapterOptions): T {
  const zoned = toZoned(date, options?.timeZone).set(START_OF_DAY_FIELDS);
  return fromZonedLike(date, zoned);
}

export function endOfDay<T extends Date>(date: T, options?: AdapterOptions): T {
  const zoned = toZoned(date, options?.timeZone).set(END_OF_DAY_FIELDS);
  return fromZonedLike(date, zoned);
}

export function startOfMonth<T extends Date>(date: T, options?: AdapterOptions): T {
  const zoned = toZoned(date, options?.timeZone);
  return fromZonedLike(date, intlStartOfMonth(zoned).set(START_OF_DAY_FIELDS));
}

export function endOfMonth<T extends Date>(date: T, options?: AdapterOptions): T {
  const zoned = toZoned(date, options?.timeZone);
  return fromZonedLike(date, intlEndOfMonth(zoned).set(END_OF_DAY_FIELDS));
}

export function startOfYear<T extends Date>(date: T, options?: AdapterOptions): T {
  const zoned = toZoned(date, options?.timeZone);
  return fromZonedLike(date, intlStartOfYear(zoned).set(START_OF_DAY_FIELDS));
}

export function endOfYear<T extends Date>(date: T, options?: AdapterOptions): T {
  const zoned = toZoned(date, options?.timeZone);
  return fromZonedLike(date, intlEndOfYear(zoned).set(END_OF_DAY_FIELDS));
}

export function startOfWeek<T extends Date>(date: T, options?: WeekOptions): T {
  const zoned = toZoned(date, options?.timeZone);
  const locale = options?.locale ?? getDefaultLocale();
  const firstDay =
    options?.weekStartsOn !== undefined ? WEEKDAY_BY_INDEX[options.weekStartsOn] : undefined;
  return fromZonedLike(date, intlStartOfWeek(zoned, locale, firstDay).set(START_OF_DAY_FIELDS));
}

export function endOfWeek<T extends Date>(date: T, options?: WeekOptions): T {
  const zoned = toZoned(date, options?.timeZone);
  const locale = options?.locale ?? getDefaultLocale();
  const firstDay =
    options?.weekStartsOn !== undefined ? WEEKDAY_BY_INDEX[options.weekStartsOn] : undefined;
  return fromZonedLike(date, intlEndOfWeek(zoned, locale, firstDay).set(END_OF_DAY_FIELDS));
}

import { isToday as intlIsToday, isWeekend as intlIsWeekend } from "@internationalized/date";

import type { AdapterOptions } from "./context";
import { getDefaultLocale } from "./context";
import { assertValid, toZoned } from "./convert";

export function isBefore(date: Date, dateToCompare: Date): boolean {
  assertValid(date);
  assertValid(dateToCompare);
  return date.getTime() < dateToCompare.getTime();
}

export function isAfter(date: Date, dateToCompare: Date): boolean {
  assertValid(date);
  assertValid(dateToCompare);
  return date.getTime() > dateToCompare.getTime();
}

export function isEqual(dateLeft: Date, dateRight: Date): boolean {
  assertValid(dateLeft);
  assertValid(dateRight);
  return dateLeft.getTime() === dateRight.getTime();
}

export function compareAsc(dateLeft: Date, dateRight: Date): number {
  assertValid(dateLeft);
  assertValid(dateRight);
  const diff = dateLeft.getTime() - dateRight.getTime();
  return diff < 0 ? -1 : diff > 0 ? 1 : 0;
}

export function compareDesc(dateLeft: Date, dateRight: Date): number {
  return -compareAsc(dateLeft, dateRight);
}

/** Calendar-date equality (ignores time-of-day), evaluated in `options.timeZone`. */
export function isSameDay(dateLeft: Date, dateRight: Date, options?: AdapterOptions): boolean {
  const left = toZoned(dateLeft, options?.timeZone);
  const right = toZoned(dateRight, options?.timeZone);
  return left.year === right.year && left.month === right.month && left.day === right.day;
}

export function isSameMonth(dateLeft: Date, dateRight: Date, options?: AdapterOptions): boolean {
  const left = toZoned(dateLeft, options?.timeZone);
  const right = toZoned(dateRight, options?.timeZone);
  return left.year === right.year && left.month === right.month;
}

export function isSameYear(dateLeft: Date, dateRight: Date, options?: AdapterOptions): boolean {
  const left = toZoned(dateLeft, options?.timeZone);
  const right = toZoned(dateRight, options?.timeZone);
  return left.year === right.year;
}

/** Locale-aware weekend check (e.g. Fri/Sat counts as weekend in several Middle Eastern locales). */
export function isWeekend(date: Date, options?: AdapterOptions): boolean {
  const zoned = toZoned(date, options?.timeZone);
  return intlIsWeekend(zoned, options?.locale ?? getDefaultLocale());
}

export function isToday(date: Date, options?: AdapterOptions): boolean {
  const zoned = toZoned(date, options?.timeZone);
  return intlIsToday(zoned, zoned.timeZone);
}

export function isValid(date: unknown): date is Date {
  return date instanceof Date && !Number.isNaN(date.getTime());
}

/** Returns the earliest date, by reference (preserving its exact type — e.g. a `TZDate` stays a `TZDate` — same as real date-fns). */
export function min<T extends Date>(dates: T[]): T {
  dates.forEach(assertValid);
  return dates.reduce((earliest, d) => (d.getTime() < earliest.getTime() ? d : earliest));
}

/** Returns the latest date, by reference (preserving its exact type — same as real date-fns). */
export function max<T extends Date>(dates: T[]): T {
  dates.forEach(assertValid);
  return dates.reduce((latest, d) => (d.getTime() > latest.getTime() ? d : latest));
}

import { getLocalTimeZone } from "@internationalized/date";

/**
 * The adapter needs a locale and an IANA time zone to do calendar-aware
 * arithmetic. date-fns never asked for either of these (it always used the
 * environment's implicit locale/offset), so we keep sane defaults and let
 * consumers override them once, globally, instead of on every call — this
 * is what lets existing `addDays(date, 1)`-style call sites keep working
 * unchanged.
 */

let defaultTimeZone: string | null = null;
let defaultLocale: string | null = null;

/** Returns the time zone used by every adapter function unless overridden. */
export function getDefaultTimeZone(): string {
  return defaultTimeZone ?? getLocalTimeZone();
}

/**
 * Sets the time zone used by every adapter function unless a call passes
 * its own `timeZone` option. Defaults to the runtime's local time zone.
 */
export function setDefaultTimeZone(timeZone: string | null): void {
  defaultTimeZone = timeZone;
}

/** Returns the locale used for locale-sensitive functions (formatting, week start, weekend). */
export function getDefaultLocale(): string {
  return (
    defaultLocale ??
    (typeof Intl !== "undefined" ? Intl.DateTimeFormat().resolvedOptions().locale : "en-US")
  );
}

/** Sets the locale used for locale-sensitive functions unless a call overrides it. */
export function setDefaultLocale(locale: string | null): void {
  defaultLocale = locale;
}

/** Common options accepted by most adapter functions, mirroring date-fns's `options` bag. */
export interface AdapterOptions {
  /** IANA time zone identifier, e.g. `'America/Sao_Paulo'`. Defaults to {@link getDefaultTimeZone}. */
  timeZone?: string;
  /** BCP 47 locale identifier, e.g. `'pt-BR'`. Defaults to {@link getDefaultLocale}. */
  locale?: string;
}

import { fromDate, type ZonedDateTime } from "@internationalized/date";

import { getDefaultTimeZone } from "./context";
import { TZDate } from "./tz";

/**
 * Converts a native `Date` (an instant) into a `ZonedDateTime` (a calendar
 * date + wall-clock time + offset) in the given time zone. This is the
 * single conversion every arithmetic/comparison/boundary function in this
 * package goes through, so that `@internationalized/date`'s DST-safe,
 * calendar-aware math runs under the hood while every public function here
 * still accepts and returns plain `Date` objects — the same as date-fns.
 *
 * When no explicit `timeZone` is given and `date` is a `TZDate`, its own
 * zone wins over the adapter's global default — the same rule date-fns v4
 * itself applies via `constructFrom`, and what lets a `TZDate` chain through
 * `addDays(startOfWeek(tzDate), 1)` without repeating `timeZone` at each step.
 */
export function toZoned(date: Date, timeZone?: string): ZonedDateTime {
  assertValid(date);
  const tz = timeZone ?? (date instanceof TZDate ? date.timeZone : getDefaultTimeZone());
  return fromDate(date, tz);
}

/** Converts a `ZonedDateTime` back to a native `Date` instant. */
export function fromZoned(zoned: ZonedDateTime): Date {
  return zoned.toDate();
}

/**
 * Like `fromZoned`, but preserves `reference`'s exact type (mirrors date-fns
 * v4's own generic `constructFrom<DateType extends Date>`): if `reference`
 * is a `TZDate`, the result is a `TZDate` in the same zone (still typed
 * `T`); otherwise a plain `Date`. Every arithmetic/boundary function that
 * transforms a `Date` into another `Date` uses this instead of `fromZoned`,
 * and is itself generic over `T extends Date`, so a call site typed
 * `addDays(startOfWeek(tzDate), 1)` — where `tzDate: TZDate` — infers a
 * `TZDate` result with no cast, exactly like real date-fns's own types do.
 */
export function fromZonedLike<T extends Date>(reference: T, zoned: ZonedDateTime): T {
  // The cast is safe: when `reference` is a `TZDate`, the runtime branch
  // below always constructs one, and `T` was inferred from `reference`
  // itself at the call site.
  return (
    reference instanceof TZDate
      ? new TZDate(zoned.toDate().getTime(), reference.timeZone)
      : zoned.toDate()
  ) as T;
}

/** Throws the same kind of `RangeError` `date-fns` throws for an invalid Date. */
export function assertValid(date: Date): void {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    throw new RangeError("Invalid time value");
  }
}

import type { AdapterOptions } from "./context";
import { assertValid, toZoned } from "./convert";

const MS_PER_SECOND = 1000;
const MS_PER_MINUTE = 60 * MS_PER_SECOND;
const MS_PER_HOUR = 60 * MS_PER_MINUTE;

/**
 * "Exact" differences work purely on the instant (epoch milliseconds), just
 * like date-fns's own `differenceInHours`/`differenceInMinutes`/etc. They
 * don't need calendar awareness, so no conversion through
 * `@internationalized/date` happens here — only `assertValid` keeps the
 * same "throw on Invalid Date" behaviour as date-fns.
 */
function exactDiff(dateLeft: Date, dateRight: Date, unitMs: number): number {
  assertValid(dateLeft);
  assertValid(dateRight);
  const diff = (dateLeft.getTime() - dateRight.getTime()) / unitMs;
  return diff > 0 ? Math.floor(diff) : Math.ceil(diff);
}

export function differenceInMilliseconds(dateLeft: Date, dateRight: Date): number {
  assertValid(dateLeft);
  assertValid(dateRight);
  return dateLeft.getTime() - dateRight.getTime();
}
export function differenceInSeconds(dateLeft: Date, dateRight: Date): number {
  return exactDiff(dateLeft, dateRight, MS_PER_SECOND);
}
export function differenceInMinutes(dateLeft: Date, dateRight: Date): number {
  return exactDiff(dateLeft, dateRight, MS_PER_MINUTE);
}
export function differenceInHours(dateLeft: Date, dateRight: Date): number {
  return exactDiff(dateLeft, dateRight, MS_PER_HOUR);
}

/**
 * "Calendar" differences count whole calendar units crossed, the way a
 * person reading a calendar would — this is where handing the math to
 * `@internationalized/date` actually pays off, since it resolves each side
 * to a calendar date in the given time zone before comparing fields,
 * instead of assuming a fixed 24h/30-day/365-day unit like naive
 * millisecond division would.
 */
export function differenceInCalendarDays(
  dateLeft: Date,
  dateRight: Date,
  options?: AdapterOptions,
): number {
  const tz = options?.timeZone;
  const leftMidnight = toZoned(dateLeft, tz)
    .set({ hour: 0, minute: 0, second: 0, millisecond: 0 })
    .toDate();
  const rightMidnight = toZoned(dateRight, tz)
    .set({ hour: 0, minute: 0, second: 0, millisecond: 0 })
    .toDate();
  return Math.round((leftMidnight.getTime() - rightMidnight.getTime()) / (MS_PER_HOUR * 24));
}

/** Like `differenceInCalendarDays`, but only counts a day once a full 24h-equivalent has elapsed (date-fns semantics). */
export function differenceInDays(
  dateLeft: Date,
  dateRight: Date,
  options?: AdapterOptions,
): number {
  const calendarDays = differenceInCalendarDays(dateLeft, dateRight, options);
  const left = toZoned(dateLeft, options?.timeZone);
  const right = toZoned(dateRight, options?.timeZone).add({
    days: calendarDays,
  });
  const isLastDayNotFull =
    (calendarDays > 0 && left.compare(right) < 0) || (calendarDays < 0 && left.compare(right) > 0);
  return isLastDayNotFull ? calendarDays - Math.sign(calendarDays) : calendarDays;
}

export function differenceInCalendarWeeks(
  dateLeft: Date,
  dateRight: Date,
  options?: AdapterOptions,
): number {
  const days = differenceInCalendarDays(dateLeft, dateRight, options);
  return days > 0 ? Math.floor(days / 7) : Math.ceil(days / 7);
}

export function differenceInCalendarMonths(
  dateLeft: Date,
  dateRight: Date,
  options?: AdapterOptions,
): number {
  const left = toZoned(dateLeft, options?.timeZone);
  const right = toZoned(dateRight, options?.timeZone);
  return (left.year - right.year) * 12 + (left.month - right.month);
}

export function differenceInCalendarYears(
  dateLeft: Date,
  dateRight: Date,
  options?: AdapterOptions,
): number {
  const left = toZoned(dateLeft, options?.timeZone);
  const right = toZoned(dateRight, options?.timeZone);
  return left.year - right.year;
}

/** Like `differenceInCalendarMonths`, but only counts a month once it has fully elapsed (date-fns semantics). */
export function differenceInMonths(
  dateLeft: Date,
  dateRight: Date,
  options?: AdapterOptions,
): number {
  const calendarMonths = differenceInCalendarMonths(dateLeft, dateRight, options);
  const left = toZoned(dateLeft, options?.timeZone);
  const right = toZoned(dateRight, options?.timeZone).add({
    months: calendarMonths,
  });
  const isLastMonthNotFull =
    (calendarMonths > 0 && left.compare(right) < 0) ||
    (calendarMonths < 0 && left.compare(right) > 0);
  return isLastMonthNotFull ? calendarMonths - Math.sign(calendarMonths) : calendarMonths;
}

/** Like `differenceInCalendarYears`, but only counts a year once it has fully elapsed (date-fns semantics). */
export function differenceInYears(
  dateLeft: Date,
  dateRight: Date,
  options?: AdapterOptions,
): number {
  const months = differenceInMonths(dateLeft, dateRight, options);
  return Math.trunc(months / 12);
}

import {
  parseAbsolute,
  parseDate,
  parseDateTime,
  parseZonedDateTime,
  type ZonedDateTime,
} from "@internationalized/date";

import type { AdapterOptions } from "./context";
import { getDefaultLocale, getDefaultTimeZone } from "./context";
import { assertValid, toZoned } from "./convert";

// ---------------------------------------------------------------------------
// parseISO
// ---------------------------------------------------------------------------

const HAS_BRACKET_TZ = /\[[^\]]+\]\s*$/;
const HAS_OFFSET_OR_Z = /(Z|[+-]\d{2}:?\d{2})\s*(\[[^\]]+\])?$/;
const HAS_TIME = /T|\s\d{2}:\d{2}/;

/**
 * Mirrors date-fns's `parseISO`: parses an ISO 8601 string into a native
 * `Date`. A bare date/time with no offset is interpreted as wall-clock time
 * in `options.timeZone` (default: the adapter's default time zone) — the
 * same "local time" behaviour date-fns' `parseISO` has by default.
 */
export function parseISO(argument: string, options?: AdapterOptions): Date {
  const value = argument.trim();
  const timeZone = options?.timeZone ?? getDefaultTimeZone();

  try {
    if (HAS_BRACKET_TZ.test(value)) {
      return parseZonedDateTime(value).toDate();
    }
    if (HAS_OFFSET_OR_Z.test(value)) {
      return parseAbsolute(value, timeZone).toDate();
    }
    if (HAS_TIME.test(value)) {
      return parseDateTime(value.replace(" ", "T")).toDate(timeZone);
    }
    return parseDate(value).toDate(timeZone);
  } catch {
    return new Date(NaN);
  }
}

// ---------------------------------------------------------------------------
// formatISO
// ---------------------------------------------------------------------------

function pad(n: number, width = 2): string {
  return String(Math.abs(n)).padStart(width, "0");
}

function offsetToString(offsetMs: number): string {
  const sign = offsetMs < 0 ? "-" : "+";
  const totalMinutes = Math.round(Math.abs(offsetMs) / 60000);
  return `${sign}${pad(Math.floor(totalMinutes / 60))}:${pad(totalMinutes % 60)}`;
}

export interface FormatISOOptions extends AdapterOptions {
  representation?: "complete" | "date" | "time";
}

/** Mirrors date-fns's `formatISO`: `2019-09-18T19:00:52+01:00` by default. */
export function formatISO(date: Date, options?: FormatISOOptions): string {
  assertValid(date);
  const zoned = toZoned(date, options?.timeZone);
  const datePart = `${pad(zoned.year, 4)}-${pad(zoned.month)}-${pad(zoned.day)}`;
  const timePart = `${pad(zoned.hour)}:${pad(zoned.minute)}:${pad(zoned.second)}${offsetToString(zoned.offset)}`;
  switch (options?.representation) {
    case "date":
      return datePart;
    case "time":
      return timePart;
    default:
      return `${datePart}T${timePart}`;
  }
}

// ---------------------------------------------------------------------------
// format (date-fns-style format tokens)
// ---------------------------------------------------------------------------

/** A UTC-anchored plain Date carrying only the Y/M/D of a ZonedDateTime, used solely to borrow Intl's locale name tables. */
function fieldsAnchor(zoned: ZonedDateTime): Date {
  return new Date(Date.UTC(zoned.year, zoned.month - 1, zoned.day, zoned.hour));
}

function localeName(
  zoned: ZonedDateTime,
  locale: string,
  options: Intl.DateTimeFormatOptions,
): string {
  return new Intl.DateTimeFormat(locale, {
    ...options,
    timeZone: "UTC",
  }).format(fieldsAnchor(zoned));
}

function ordinalSuffix(day: number): string {
  if (day > 3 && day < 21) return "th";
  switch (day % 10) {
    case 1:
      return "st";
    case 2:
      return "nd";
    case 3:
      return "rd";
    default:
      return "th";
  }
}

function hour12(hour: number): number {
  const h = hour % 12;
  return h === 0 ? 12 : h;
}

/**
 * Supported date-fns format tokens. This is a deliberately curated subset —
 * the tokens used in the overwhelming majority of real codebases — rather
 * than a full reimplementation of date-fns's ~40 tokens. Anything not
 * listed throws instead of silently formatting wrong; the message points
 * at `Intl.DateTimeFormat`, which is what `@internationalized/date`'s own
 * maintainers recommend for formatting.
 */
function buildTokenMap(zoned: ZonedDateTime, locale: string): Record<string, () => string> {
  return {
    yyyy: () => pad(zoned.year, 4),
    yy: () => pad(zoned.year % 100),
    y: () => String(zoned.year),
    MMMM: () => localeName(zoned, locale, { month: "long" }),
    MMM: () => localeName(zoned, locale, { month: "short" }),
    MM: () => pad(zoned.month),
    M: () => String(zoned.month),
    dd: () => pad(zoned.day),
    d: () => String(zoned.day),
    do: () => `${zoned.day}${ordinalSuffix(zoned.day)}`,
    EEEE: () => localeName(zoned, locale, { weekday: "long" }),
    EEE: () => localeName(zoned, locale, { weekday: "short" }),
    EEEEE: () => localeName(zoned, locale, { weekday: "narrow" }),
    HH: () => pad(zoned.hour),
    H: () => String(zoned.hour),
    hh: () => pad(hour12(zoned.hour)),
    h: () => String(hour12(zoned.hour)),
    mm: () => pad(zoned.minute),
    m: () => String(zoned.minute),
    ss: () => pad(zoned.second),
    s: () => String(zoned.second),
    SSS: () => pad(zoned.millisecond, 3),
    a: () =>
      localeName(zoned, locale, { hour: "numeric", hour12: true }).replace(/[\d:\s]/g, "") ||
      (zoned.hour < 12 ? "AM" : "PM"),
    X: () => offsetToString(zoned.offset).replace(":00", "").replace(":", ""),
    XX: () => offsetToString(zoned.offset).replace(":", ""),
    XXX: () => offsetToString(zoned.offset),
    // date-fns's localized-date family (no time component); the lowercase
    // "p" time family isn't implemented (no caller needs it yet — add it the
    // same way if one shows up).
    PPPP: () => localeName(zoned, locale, { dateStyle: "full" }),
    PPP: () => localeName(zoned, locale, { dateStyle: "long" }),
    PP: () => localeName(zoned, locale, { dateStyle: "medium" }),
    P: () => localeName(zoned, locale, { dateStyle: "short" }),
  };
}

// Splits a format string into quoted literals ('...' / '' for a literal quote) and letter runs, date-fns style.
const TOKEN_REGEXP = /(''|'(?:[^']|'')*'|[a-zA-Z]+|[^a-zA-Z']+)/g;

/**
 * Mirrors date-fns's `format(date, formatStr, options?)` for the token
 * subset listed in {@link buildTokenMap}. Existing calls such as
 * `format(date, 'dd/MM/yyyy')` keep working unchanged.
 */
export function format(date: Date, formatStr: string, options?: AdapterOptions): string {
  assertValid(date);
  const zoned = toZoned(date, options?.timeZone);
  const locale = options?.locale ?? getDefaultLocale();
  const tokenMap = buildTokenMap(zoned, locale);
  const parts = formatStr.match(TOKEN_REGEXP) ?? [];

  return parts
    .map((part) => {
      if (part.startsWith("'")) {
        if (part === "''") return "'";
        return part.slice(1, -1).replace(/''/g, "'");
      }
      if (!/^[a-zA-Z]+$/.test(part)) return part;
      const resolver = tokenMap[part];
      if (!resolver) {
        throw new RangeError(
          `format: unsupported token "${part}". This adapter covers the common date-fns tokens; ` +
            "for anything else, format the ZonedDateTime fields yourself or use Intl.DateTimeFormat directly.",
        );
      }
      return resolver();
    })
    .join("");
}

import {
  CalendarDateTime,
  fromDate,
  getDayOfWeek,
  toZoned as intlToZoned,
  type ZonedDateTime,
} from "@internationalized/date";

// en-US's first day of the week is Sunday, so this always yields the fixed
// Sunday=0..Saturday=6 index JS Date#getDay() uses, regardless of the
// display locale a consumer configures elsewhere.
const FIXED_WEEK_LOCALE = "en-US";

function resolveEpochMs(dateArgs: Array<number | string>, timeZone: string): number {
  if (dateArgs.length === 0) return Date.now();
  if (dateArgs.length === 1) {
    const [value] = dateArgs;
    return typeof value === "string" ? Date.parse(value) : value;
  }
  const [year, month, day = 1, hours = 0, minutes = 0, seconds = 0, ms = 0] = dateArgs as number[];
  const wallClock = new CalendarDateTime(year, month + 1, day, hours, minutes, seconds, ms);
  return intlToZoned(wallClock, timeZone).toDate().getTime();
}

/**
 * Drop-in replacement for `@date-fns/tz`'s `TZDate`: a `Date` subclass whose
 * getters read wall-clock fields in `timeZone` instead of the process's own
 * zone, backed by `@internationalized/date` instead of `@date-fns/tz`'s own
 * Intl-parsing implementation. The constructor mirrors `Date`'s own overload
 * set with `timeZone` appended as the final argument — `new TZDate(tz)` (now),
 * `new TZDate(epochMs, tz)`, `new TZDate(year, month, day, ..., tz)` — so an
 * existing `new TZDate(...)` call site importing from `@date-fns/tz` needs
 * only its import path swapped to `@/lib/date-fns-compat`.
 */
class TZDate extends Date {
  readonly timeZone: string;
  // Not readonly: the set* overrides below mutate it in step with the
  // instance's own instant (see applyZonedSet) so getters stay consistent
  // after a native-style setDate/setHours/etc. call.
  zoned: ZonedDateTime;

  constructor(timeZone: string);
  constructor(value: number | string, timeZone: string);
  constructor(year: number, month: number, timeZone: string);
  constructor(year: number, month: number, day: number, timeZone: string);
  constructor(year: number, month: number, day: number, hours: number, timeZone: string);
  constructor(
    year: number,
    month: number,
    day: number,
    hours: number,
    minutes: number,
    timeZone: string,
  );
  constructor(
    year: number,
    month: number,
    day: number,
    hours: number,
    minutes: number,
    seconds: number,
    timeZone: string,
  );
  constructor(
    year: number,
    month: number,
    day: number,
    hours: number,
    minutes: number,
    seconds: number,
    ms: number,
    timeZone: string,
  );
  constructor(...args: [...Array<number | string>, string]) {
    const timeZone = args[args.length - 1] as string;
    const dateArgs = args.slice(0, -1);
    super(resolveEpochMs(dateArgs, timeZone));
    this.timeZone = timeZone;
    this.zoned = fromDate(this, timeZone);
  }

  getFullYear(): number {
    return this.zoned.year;
  }
  getMonth(): number {
    return this.zoned.month - 1; // internationalized/date is 1-indexed; Date is 0-indexed
  }
  getDate(): number {
    return this.zoned.day;
  }
  getDay(): number {
    return getDayOfWeek(this.zoned, FIXED_WEEK_LOCALE);
  }
  getHours(): number {
    return this.zoned.hour;
  }
  getMinutes(): number {
    return this.zoned.minute;
  }
  getSeconds(): number {
    return this.zoned.second;
  }
  getMilliseconds(): number {
    return this.zoned.millisecond;
  }

  /**
   * Mutates the instance in place (matching native `Date` set* semantics,
   * including *overflow* — `setMonth(13)` rolls into next year, `setDate(0)`
   * rolls back to the last day of the previous month, `setHours(25)` rolls
   * into the next day). `@internationalized/date`'s own `.set()` instead
   * *constrains* (clamps) out-of-range fields, which is the wrong behavior
   * here: real date-fns's own `addMonths` deliberately exploits native
   * overflow (`endOfDesiredMonth.setMonth(month + 1, 0)` to land on "the day
   * before the 1st of next month" = the last day of the target month) to
   * implement ITS OWN clamping on top — so this class has to reproduce raw
   * ECMA overflow, not `@internationalized/date`'s clamping, or that trick
   * silently breaks.
   *
   * The fix mirrors ECMA-262's own `MakeDay`/`MakeDate` algorithm: normalize
   * year+month into a valid (year, month) pair first (months are carried
   * into years via plain integer math, not calendar-aware), land on day 1 of
   * that month (always valid, no clamping possible), then reach the
   * requested day via pure day-count *addition* — which `@internationalized/
   * date`'s `.add({ days })` does with correct carrying and no clamping,
   * since every integer day offset from a valid date is itself valid.
   */
  private applyDateOverflow(year: number, month0: number, day: number): number {
    const totalMonths = year * 12 + month0;
    const normYear = Math.floor(totalMonths / 12);
    const normMonth1 = (((totalMonths % 12) + 12) % 12) + 1;
    const firstOfMonth = this.zoned.set({
      year: normYear,
      month: normMonth1,
      day: 1,
    });
    const target = firstOfMonth.add({ days: day - 1 });
    this.zoned = target;
    const epochMs = target.toDate().getTime();
    this.setTime(epochMs);
    return epochMs;
  }

  /** Same overflow reasoning as {@link applyDateOverflow}, for the time fields. */
  private applyTimeOverflow(
    hours: number,
    minutes: number,
    seconds: number,
    milliseconds: number,
  ): number {
    const midnight = this.zoned.set({
      hour: 0,
      minute: 0,
      second: 0,
      millisecond: 0,
    });
    const target = midnight.add({ hours, minutes, seconds, milliseconds });
    this.zoned = target;
    const epochMs = target.toDate().getTime();
    this.setTime(epochMs);
    return epochMs;
  }

  setFullYear(year: number, month?: number, date?: number): number {
    return this.applyDateOverflow(
      year,
      month !== undefined ? month : this.getMonth(),
      date !== undefined ? date : this.getDate(),
    );
  }
  setMonth(month: number, date?: number): number {
    return this.applyDateOverflow(
      this.getFullYear(),
      month,
      date !== undefined ? date : this.getDate(),
    );
  }
  setDate(date: number): number {
    return this.applyDateOverflow(this.getFullYear(), this.getMonth(), date);
  }
  setHours(hours: number, min?: number, sec?: number, ms?: number): number {
    return this.applyTimeOverflow(
      hours,
      min !== undefined ? min : this.getMinutes(),
      sec !== undefined ? sec : this.getSeconds(),
      ms !== undefined ? ms : this.getMilliseconds(),
    );
  }
  setMinutes(min: number, sec?: number, ms?: number): number {
    return this.applyTimeOverflow(
      this.getHours(),
      min,
      sec !== undefined ? sec : this.getSeconds(),
      ms !== undefined ? ms : this.getMilliseconds(),
    );
  }
  setSeconds(sec: number, ms?: number): number {
    return this.applyTimeOverflow(
      this.getHours(),
      this.getMinutes(),
      sec,
      ms !== undefined ? ms : this.getMilliseconds(),
    );
  }
  setMilliseconds(ms: number): number {
    return this.applyTimeOverflow(this.getHours(), this.getMinutes(), this.getSeconds(), ms);
  }

  /** Re-expresses the same instant in a different zone (matches @date-fns/tz's TZDate#withTimeZone). */
  withTimeZone(timeZone: string): TZDate {
    return new TZDate(this.getTime(), timeZone);
  }

  /**
   * Minutes to *add* to local time to get UTC — native `Date`'s own sign
   * convention (positive for zones behind UTC, e.g. `America/Sao_Paulo`
   * returns `180`). Unoverridden, this would return the *process's* offset
   * instead of `this.timeZone`'s.
   */
  getTimezoneOffset(): number {
    return -(this.zoned.offset / 60_000);
  }

  /**
   * `toLocaleString`/`toLocaleDateString`/`toLocaleTimeString` need no
   * zoned-field math at all: native `Date.prototype`'s own implementation
   * already reads `this.getTime()` (correct, inherited, unoverridden) — it
   * only needs `timeZone` in its options to render in the right zone
   * instead of the process's. An explicit `options.timeZone` from the
   * caller still wins.
   */
  toLocaleString(locales?: Intl.LocalesArgument, options?: Intl.DateTimeFormatOptions): string {
    return Date.prototype.toLocaleString.call(this, locales, {
      ...options,
      timeZone: options?.timeZone || this.timeZone,
    });
  }
  toLocaleDateString(locales?: Intl.LocalesArgument, options?: Intl.DateTimeFormatOptions): string {
    return Date.prototype.toLocaleDateString.call(this, locales, {
      ...options,
      timeZone: options?.timeZone || this.timeZone,
    });
  }
  toLocaleTimeString(locales?: Intl.LocalesArgument, options?: Intl.DateTimeFormatOptions): string {
    return Date.prototype.toLocaleTimeString.call(this, locales, {
      ...options,
      timeZone: options?.timeZone || this.timeZone,
    });
  }

  /** ISO 8601 with this instance's own zone offset (not "Z") — matches real @date-fns/tz's TZDate#toISOString. */
  toISOString(): string {
    const z = this.zoned;
    const pad = (n: number, width = 2) => String(n).padStart(width, "0");
    const offsetMin = -this.getTimezoneOffset();
    const sign = offsetMin < 0 ? "-" : "+";
    const abs = Math.abs(offsetMin);
    return (
      `${pad(z.year, 4)}-${pad(z.month)}-${pad(z.day)}` +
      `T${pad(z.hour)}:${pad(z.minute)}:${pad(z.second)}.${String(z.millisecond).padStart(3, "0")}` +
      `${sign}${pad(Math.floor(abs / 60))}:${pad(abs % 60)}`
    );
  }

  /** "Tue Aug 13 2024" in this instance's own zone — locale-invariant, matching native Date's own toDateString format. */
  toDateString(): string {
    return new Intl.DateTimeFormat("en-US", {
      weekday: "short",
      month: "short",
      day: "2-digit",
      year: "numeric",
      timeZone: this.timeZone,
    })
      .format(this)
      .replaceAll(",", "");
  }

  /** "07:50:19 GMT+0800" in this instance's own zone — a simplified form of native Date's toTimeString (omits the parenthesized zone name). */
  toTimeString(): string {
    const z = this.zoned;
    const pad = (n: number, width = 2) => String(n).padStart(width, "0");
    const offsetMin = -this.getTimezoneOffset();
    const sign = offsetMin < 0 ? "-" : "+";
    const abs = Math.abs(offsetMin);
    return `${pad(z.hour)}:${pad(z.minute)}:${pad(z.second)} GMT${sign}${pad(Math.floor(abs / 60))}${pad(abs % 60)}`;
  }

  toString(): string {
    return `${this.toDateString()} ${this.toTimeString()}`;
  }

  /**
   * Real date-fns's own `constructFrom` (see `date-fns/constructFrom.js`)
   * looks for this exact well-known symbol before falling back to
   * `new date.constructor(value)` — which would break here since our
   * constructor's last argument must be a `timeZone` string, not just an
   * epoch value. `Symbol.for` returns the same global symbol regardless of
   * which package requests it, so implementing this needs no dependency on
   * `date-fns` itself: any date-fns-ecosystem function (real date-fns
   * included, e.g. if a test imports it for parity checks) that receives our
   * `TZDate` as its reference date reconstructs another `TZDate` in the same
   * zone instead of silently misconstructing a bad value.
   */
  [Symbol.for("constructDateFrom")](value: number | Date): TZDate {
    return new TZDate(value instanceof Date ? value.getTime() : value, this.timeZone);
  }
}

export { TZDate };

import { startOfWeek, startOfYear, type WeekOptions } from "./boundaries";
import { differenceInCalendarDays } from "./difference";

/**
 * Locale-agnostic week-of-year: 1 + the number of week-boundaries crossed
 * since the week containing Jan 1. This is a deliberate simplification of
 * date-fns's `getWeek` (which also consults the locale's
 * `firstWeekContainsDate` for the year-boundary edge case — a date in late
 * December can belong to "week 1" of the following year under some
 * conventions) — most call sites use this for a display gutter number and
 * always pass `weekStartsOn` explicitly, so this covers the common case
 * without reimplementing full CLDR week-numbering.
 */
export function getWeek(date: Date, options?: WeekOptions): number {
  const firstWeekOfYearStart = startOfWeek(startOfYear(date, options), options);
  const dateWeekStart = startOfWeek(date, options);
  const days = differenceInCalendarDays(dateWeekStart, firstWeekOfYearStart, options);
  return Math.floor(days / 7) + 1;
}
